const success=<T>(result:{response:Response;data?:T;error?:{code:string}})=>{expect(result.response.status,result.error?.code).toBe(200);if(!result.data)throw new Error('HTTP_DATA_REQUIRED');return result.data;};
const diagnosticQuery=Client.prototype.query;
Client.prototype.query=(function(this:Client,config:string|QueryConfig,...args:unknown[]){const result=Reflect.apply(diagnosticQuery,this,[config,...args]);if(result&&typeof result.then==='function')return Promise.resolve(result).catch((error:unknown)=>{if(error instanceof Error&&'code' in error&&typeof error.code==='string'){const code=/^[A-Z][A-Z0-9_]+$/.test(error.message)?error.message:null,frames='where' in error&&typeof error.where==='string'?error.where.split('\n').filter(line=>/^PL\/pgSQL function [a-z_]+\.[a-z_]+\([a-z, ]*\) line [0-9]+ at [a-z ]+$/.test(line)):[];console.error(JSON.stringify({gate:'P3_11_SQL_DIAGNOSTIC',sqlstate:error.code,code,frames}));}throw error;});return result;}) as typeof diagnosticQuery;
afterAll(()=>{Client.prototype.query=diagnosticQuery;});

