test.each(['binding','successor'] as const)('AC04 failure at the target %s after a separate source END rolls back every Owner and receipt',async(boundary)=>{
 const a=await fixture.endpoint('UNIT'),old=await fixture.entry(a),created=await fixture.apply(await fixture.input([old])),oldId=created.facts[0]!.id,unit=await fixture.base.owner.history('maker',{id:a.target.id}),target=await fixture.base.endpoint(unit.departmentId),T='2028-02-01T00:00:00.000001',f=unit.versions[0]!.facts,e=fixture.base.entry(target);if(e.action!=='CREATE')throw new Error('TEST_CREATE_REQUIRED');const rebind={...e,action:'REBIND' as const,target:{owner:'care-organization/unit' as const,id:unit.id,expectedHead:'1'},row:{...e.row,unit_id:f.source.sourceAlias,unit_code:f.unitCode,unit_name:f.unitName,unit_type:f.unitType,public_phone:f.publicPhone??'',service_description:f.serviceDescription??'',receiving_rule_ref:f.receivingRuleReference??'',valid_from:T}},ui=await fixture.base.input([rebind]),us=await fixture.base.owner.stage('maker',ui);await fixture.base.owner.verify('reviewer',fixture.base.verification(ui,us));
 const end={...old,action:'END' as const,target:{owner:'location-master/location-use' as const,id:oldId,expectedHead:'1'},endAt:T,row:{...old.row,record_status:'RETIRED' as const}},next=await fixture.entry({...a,campus:target.campus,location:await fixture.newLocation(target.campus.id)});next.row.valid_from=T;const parts=[];for(const row of [end,next]){const data=await fixture.input([row]),input=await fixture.owner.stage('maker',data);await fixture.owner.verify('reviewer',fixture.verification(data,input));parts.push({owner:'LOCATION_USE' as const,...input,contractVersionId:fixture.contract!.versionId});}
 const root=await owner.stage('maker',{requestId:randomUUID(),campus:'NORTH',kind:'MOVE',cutover:T,policy:'TEST_POLICY_ONLY',reason:'TEST source END precedes target producer and successor',members:[parts[1]!,{owner:'UNIT',...us,contractVersionId:fixture.base.contract!.versionId},parts[0]!]});await owner.verify('reviewer',{requestId:randomUUID(),inputId:root.inputId,inputDigest:root.digest,reason:'TEST independent full source and target scopes',policy:'TEST_POLICY_ONLY'});const requestId=randomUUID(),candidate=await owner.plan('maker',{inputId:root.inputId,requestId});await owner.readApplyCandidate('reviewer',{candidateId:candidate.candidateId});await owner.approveApplyUnit('reviewer',candidate);
 const table=boundary==='binding'?'care_organization.binding_version':'location_master.use_version',condition=boundary==='binding'?'NEW.number=1':"NEW.action='CREATE'",before=Client.prototype.query;let observed=false;
 peer(receipt.name,`CREATE FUNCTION care_organization.p3_11_target_fail() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF ${condition} THEN IF EXISTS(SELECT 1 FROM location_master.use_version WHERE use_id='${oldId}'::uuid AND action='END') THEN RAISE EXCEPTION 'TEST_TARGET_FAILURE_AFTER_SOURCE_END';ELSE RAISE EXCEPTION 'TEST_TARGET_FAILURE_BEFORE_SOURCE_END';END IF;END IF;RETURN NEW;END $$;CREATE TRIGGER p3_11_target_fail BEFORE INSERT ON ${table} FOR EACH ROW EXECUTE FUNCTION care_organization.p3_11_target_fail();`);
 Client.prototype.query=(function(this:Client,config:string|QueryConfig,...args:unknown[]){const value=Reflect.apply(before,this,[config,...args]);if(value&&typeof value.then==='function')return Promise.resolve(value).catch((error:unknown)=>{if(error instanceof Error&&error.message==='TEST_TARGET_FAILURE_AFTER_SOURCE_END')observed=true;throw error;});return value;}) as typeof before;
 try{await expect(owner.applyUnit('maker',{candidateId:candidate.candidateId,requestId})).rejects.toThrow('APPLY_FAILED');expect(observed).toBe(true);}finally{Client.prototype.query=before;peer(receipt.name,`DROP TRIGGER p3_11_target_fail ON ${table};DROP FUNCTION care_organization.p3_11_target_fail();`);}
 expect((await fixture.owner.history('maker',{id:oldId})).versions).toHaveLength(1);expect((await fixture.base.owner.history('maker',{id:unit.id})).versions).toHaveLength(1);expect(await owner.resumeOutcome('maker',{candidateId:candidate.candidateId,requestId})).toBeNull();expect((await owner.applyUnit('maker',{candidateId:candidate.candidateId,requestId})).status).toBe('COMMITTED');expect(await owner.reconcileCommittedUnit('maker',{candidateId:candidate.candidateId,requestId})).toMatchObject({status:'MATCHED'});
});

